Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := Asan.M.loaded_segments.
#[local] Abbreviation cellA := (cell Asan.M.loaded_segments).
#[local] Abbreviation wrA := (wr Asan.M.loaded_segments).
#[local] Abbreviation wokA := (wok Asan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).
Set Printing Depth 1000000. Set Printing Width 10000.
Ltac showst := lazymatch goal with |- msteps _ (mkst ?R ?P ?MM _) _ => idtac "REGS" R; idtac "PC" P; idtac "MEM" MM | |- ?G => idtac "GOAL" G end; fail "SHOWST".

Definition art_ic_size (c : Z) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 1 "U0;Lc;Ri0;m1;RNL~Ri1;i0;A2;k2;r1;A1;o3;Y4;f;2;A1;o3;Y6;00;A1;k4;r1;").
Definition art_ic_mc (c : Z) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S2;Y1;0;Y3;0;Lc;Ri0;A2;k5;A1;o3;#0;A2;k6;A1;o3;o7;A2;k8;A1;o3;#1;A2;k9;A1;o3;Y10;000;A1;k10;r1;").

Fixpoint art_ic_mem (M : word -> option byte) (ca : Z) (k : nat) : word -> option byte :=
  match k with
  | O => M
  | S k' => Wn 8 (Wn 4 (art_ic_mem M ca k') (ca + 80 * Z.of_nat k + 4) (art_ic_mc (Z.of_nat k))) (ca + 80 * Z.of_nat k + 8) (art_ic_size (Z.of_nat k))
  end.

Lemma art_ic_mem_S : forall M ca k,
  art_ic_mem M ca (S k) = Wn 8 (Wn 4 (art_ic_mem M ca k) (ca + 80 * (Z.of_nat k + 1) + 4) (art_ic_mc (Z.of_nat k + 1))) (ca + 80 * (Z.of_nat k + 1) + 8) (art_ic_size (Z.of_nat k + 1)).
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S20;Y3;0;P~RA1;i11;A1;o12;Y6;00;A1;i13;A1;i11;A1;o12;#0;A1;k17;r1;A1;k16;#2;N8;N4;A3;k20;r4;r3;r2;A1;o3;Y6;10;A2;k21;r3;A2;k5;#7;r1;Y2;0;A1;o3;#9;A1;o3;#0;A1;o3;o7;A2;k21;A1;k17;r2;#12;A2;k21;r3;A2;k5;#7;#13;Lz;Ri0;A3;i18;#1;A4;k19;#4;A4;k19;#5;#6;A2;k21;#8;#10;A1;k22;r1;A2;k21;#8;#11;A1;k10;r1;A4;k19;#4;A4;k19;#5;#6;A2;k21;#14;#10;A1;k22;#13;A2;k21;#14;#11;A1;k10;#13;A2;k21;#2;#12;A2;k21;r2;A2;k5;#7;#16;A4;k19;#4;A4;k19;#5;A3;k20;r3;r2;r1;A2;k21;#17;#10;A1;k22;#16;A2;k21;#17;#11;A1;k10;#16;A1;o26;r1;LM;R#1;Lca;Ri0;Lk;Ri14;cdA6;k15;i0;#3;#15;A6;k23;i0;#16;#15;A2;o24;#1;#18;#3;A1;k25;#2;A1;k17;#19;A1;k27;r1;A3;i18;#1;A3;k20;r3;r2;#19;#18;").
Qed.

